-- =================================================================
-- MakeIt // HQ — øvelsesbibliotek-udvidelse (188 MoveKit-øvelser)
-- =================================================================
-- AI-genereret coaching-data (draft) fra MoveKit-biblioteket. ALLE
-- importeres med is_published=false — Munk reviewer og publicerer i
-- batches via coach-fladerne. demo_asset_url sættes separat ved
-- video-ingestion. Muskel-highlighting + cues virker uden video.
--
-- Idempotent: upsert on slug. Genereret af scripts/gen-exercise-seed.mjs.

insert into public.exercises (
  slug, name, category, pattern, equipment, difficulty,
  primary_muscle, primary_muscles, secondary_muscles, tertiary_muscles,
  cue, cues, mistakes,
  why_matters, setup, progression, regression,
  display_order, is_published
) values
  ('abdominals-stretch-variation-four', 'Abdominals Stretch Variation Four', 'core', 'core', 'bodyweight', 'beginner',
   'Abs', '{abs}', '{obliques,lower_back}', '{chest,front_delts}',
   'Stræk hoften frem, åbn brystet og forlæng hele forsiden roligt.', $ex$["Stræk hoften frem og forlæng forsiden af kroppen.","Åbn brystet og træk skuldrene ned væk fra ørerne.","Hold roligt vejrtræk — slip på hver udånding.","Stop ved mild strækfølelse, ikke ved smerte i lænden."]$ex$, $ex$[{"title":"Knæk i lænden","body":"Strækket presses ind i lænden i stedet for at fordele sig. Cue: skub hoften frem og forlæng, så lænden ikke hyperextenderer."},{"title":"Holder vejret","body":"Spændt mave blokerer strækket. Træk vejret roligt og slip længere på hver udånding."}]$ex$,
   'Åbner forsiden af kroppen efter siddende arbejde og hård core-træning. Modvirker stramme hoftebøjere og en sammenkrøllet holdning.', 'Læg dig på maven, hænder under skuldrene. Pres overkroppen roligt op, mens hofte og lår bliver på gulvet.', 'Hold længere, eller pres lidt højere op for større forlængelse af maven.', 'Støt på underarmene (sphinx) i stedet for strakte arme.',
   1000, false),
  ('abdominals-stretch-variation-one', 'Abdominals Stretch Variation One', 'core', 'core', 'bodyweight', 'beginner',
   'Abs', '{abs}', '{obliques}', '{lower_back,front_delts}',
   'Forlæng maven, åbn brystet og træk roligt vejret ind i strækket.', $ex$["Forlæng hele maven ved at strække overkroppen op.","Hold hoften plantet i gulvet.","Træk skuldrene ned og åbn brystet.","Slip dybere på hver udånding."]$ex$, $ex$[{"title":"Hofte løfter sig","body":"Strækket forsvinder når hoften kommer op. Cue: hold lår og hofte i gulvet og forlæng kun overkroppen."},{"title":"Spændte skuldre","body":"Skuldrene kryber op mod ørerne. Træk dem aktivt ned og frem for at frigøre nakken."}]$ex$,
   'Grundstrækket for forsiden af kroppen. Genåbner maven efter fleksionsarbejde og lange siddende perioder.', 'Lig på maven, hænder under skuldrene, albuer let bøjet. Pres blidt op til mild strækfølelse i maven.', 'Stræk armene mere ud for en dybere forlængelse.', 'Bliv på underarmene og pres kun let op.',
   1010, false),
  ('abdominals-stretch-variation-three', 'Abdominals Stretch Variation Three', 'core', 'core', 'bodyweight', 'beginner',
   'Obliques', '{obliques,abs}', '{lats,lower_back}', '{front_delts}',
   'Forlæng og roter let til siden — træk strækket op langs flanken.', $ex$["Forlæng overkroppen og tilføj en blid rotation til siden.","Mærk strækket langs flanken og de skrå mavemuskler.","Hold hoften i gulvet under rotationen.","Skift side og hold roligt vejrtræk hele vejen."]$ex$, $ex$[{"title":"Roterer for hårdt","body":"Tvinger drejet og presser lænden. Cue: roter kun til mild stræk langs siden, aldrig ind i smerte."},{"title":"Glemmer den ene side","body":"Strækker kun den lette side. Brug lige lang tid på begge flanker for balance."}]$ex$,
   'Rammer de skrå mavemuskler og siden af kroppen, som det lige stræk ikke når. Frigør flanken og giver bedre rotationsbevægelighed.', 'Fra mave-position presser du op og roterer roligt overkroppen til den ene side, så du mærker stræk langs flanken.', 'Hold rotationen længere, eller nå armen over hovedet for mere stræk i lats.', 'Mindre rotation, og bliv på underarmene.',
   1020, false),
  ('abdominals-stretch-variation-two', 'Abdominals Stretch Variation Two', 'core', 'core', 'bodyweight', 'beginner',
   'Abs', '{abs}', '{obliques,lower_back}', '{front_delts,chest}',
   'Forlæng forsiden, hold hoften nede og pres roligt brystet op.', $ex$["Pres brystet roligt op og forlæng maven.","Hold hoften og lårene plantet i gulvet.","Lange, rolige vejrtrækninger gennem strækket.","Stop ved mild stræk — lænden skal ikke knække."]$ex$, $ex$[{"title":"Presser fra lænden","body":"Bevægelsen sker i lænden i stedet for at fordele sig over hele forsiden. Cue: forlæng først, pres derefter, og hold maven let aktiv."},{"title":"Spændt nakke","body":"Kigger for langt op og spænder nakken. Hold blikket frem og lad nakken følge rygsøjlens linje."}]$ex$,
   'En dybere version af grundstrækket der forlænger hele bugvæggen. God til at modvirke stram holdning og åbne brystkassen.', 'Lig på maven, hænder under skuldrene. Pres overkroppen op til en behagelig forlængelse uden at løfte hoften.', 'Pres højere op, eller hold længere for mere forlængelse.', 'Bliv på underarmene med en mindre bue.',
   1030, false),
  ('band-curl', 'Band Curl', 'arms', 'isolation', 'band', 'beginner',
   'Biceps', '{biceps}', '{forearms}', '{front_delts}',
   'Albuer låst ind, curl op mod skulderen og styr roligt ned mod modstanden.', $ex$["Stå på elastikken og hold albuerne låst ind ved siden.","Curl op mod skulderen og knib biceps i toppen.","Styr roligt nedad — modstanden er størst i toppen.","Hold håndleddene neutrale og lige."]$ex$, $ex$[{"title":"Albuerne svinger frem","body":"Skulderen overtager løftet. Cue: lås albuerne fast ved siden og bevæg kun underarmen."},{"title":"Slipper på vej ned","body":"Lader elastikken trække armen hurtigt ned. Modstå den excentriske fase aktivt for mere udbytte."}]$ex$,
   'Bygger biceps med konstant, stigende modstand — elastikken er hårdest i toppen, hvor bicepsens kontraktion er stærkest. Ledvenligt og let at skalere.', 'Stå midt på elastikken med fødderne skulderbredde. Grib enderne med håndfladerne fremad, albuerne ind ved siden.', 'Brug en tykkere elastik, eller stå bredere for mere forspænding.', 'Tyndere elastik, eller curl én arm ad gangen.',
   1040, false),
  ('band-high-face-pull', 'Band High Face Pull', 'shoulders', 'pull-horizontal', 'band', 'beginner',
   'Rear Delts', '{rear_delts}', '{traps,biceps}', '{forearms}',
   'Træk elastikken mod panden, albuer høje og knib skulderbladene sammen.', $ex$["Fastgør elastikken i hovedhøjde og træk mod panden.","Hold albuerne høje på linje med håndleddene.","Knib skulderbladene sammen og roter ydre.","Styr roligt tilbage uden at lade skuldrene rulle frem."]$ex$, $ex$[{"title":"Albuerne hænger lavt","body":"Trækket bliver til en rygtræk i stedet for at ramme bagskulderen. Cue: hold albuerne høje, så håndene ender ved ørerne."},{"title":"Trækker med ryggen","body":"Lats overtager bevægelsen. Hold fokus på at knibe skulderbladene og rotere udad i bagskulderen."}]$ex$,
   'Styrker bagskulder og øvre ryg samt udadrotatorer — afgørende for sund skulderbalance og holdning hos folk der presser meget.', 'Fastgør elastikken i hovedhøjde eller højere. Grib enderne, træk let bagud for forspænding, arme strakte frem.', 'Tilføj en pause med fuld udadrotation i toppen, eller brug tykkere elastik.', 'Tyndere elastik, eller træk mod brystet i stedet for panden.',
   1050, false),
  ('band-hip-abduction', 'Band Hip Abduction', 'lower-body', 'isolation', 'band', 'beginner',
   'Glutes', '{glutes}', '{adductors}', '{abs,obliques}',
   'Pres benet ud mod elastikken, hold tæerne frem og knib ballen.', $ex$["Læg elastikken om anklerne eller over knæene.","Pres benet ud til siden mod modstanden.","Hold tæerne pegende fremad — drej ikke benet udad.","Knib ballen i yderpositionen og styr roligt tilbage."]$ex$, $ex$[{"title":"Læner overkroppen væk","body":"Snyder bevægelsen med en sidebøjning. Cue: hold overkroppen lige og lad kun benet bevæge sig."},{"title":"Roterer benet udad","body":"Hoften drejer for at gøre det lettere. Hold tæerne frem, så glutes medius bliver ramt korrekt."}]$ex$,
   'Isolerer glutes medius — den stabiliserer hoften under gang, løb og squat. Stærk hofteabduktion beskytter knæene mod at falde ind.', 'Elastik om anklerne, stå på det ene ben med let bøj i støttebenet. Hold evt. fast i en støtte for balance.', 'Tykkere elastik, eller hold yderpositionen i et par sekunder.', 'Placer elastikken over knæene for kortere arm og mindre modstand.',
   1060, false),
  ('band-kneeling-pulldown', 'Band Kneeling Pulldown', 'upper-body-pull', 'pull-vertical', 'band', 'beginner',
   'Lats', '{lats}', '{biceps,rear_delts}', '{abs,traps}',
   'Træk albuerne ned mod hoften, brystet op og brug ryggen, ikke armene.', $ex$["Fastgør elastikken højt og knæl med spændt core.","Træk albuerne ned mod hoften.","Hold brystet op og knib lats i bunden.","Styr roligt op uden at lænen kollapser frem."]$ex$, $ex$[{"title":"Trækker kun med armene","body":"Biceps overtager og lats arbejder ikke. Cue: før albuerne ned og bagud, og tænk på at krumme ryggen sammen."},{"title":"Læner sig bagover","body":"Bruger overkroppens vægt i stedet for ryggen. Hold torsoen oprejst og stabil under hele trækket."}]$ex$,
   'Lærer det vertikale træk og lats-aktivering uden en kabelmaskine. Et stærkt skridt mod pull-ups og en bredere ryg.', 'Fastgør elastikken højt over hovedet. Knæl, grib enderne med strakte arme, spænd core og træk skuldrene let ned.', 'Tykkere elastik, eller hold kontraktionen i bunden.', 'Tyndere elastik, eller udfør stående med mere afstand til forankringen.',
   1070, false),
  ('band-lateral-raise', 'Band Lateral Raise', 'shoulders', 'isolation', 'band', 'beginner',
   'Side Delts', '{front_delts}', '{traps}', '{rear_delts}',
   'Løft armene ud til siden til skulderhøjde, lillefinger let op, og styr roligt ned.', $ex$["Stå på elastikken og løft armene ud til siden.","Stop ved skulderhøjde — ikke højere.","Hold en lille bøj i albuen og før lillefingeren let op.","Styr roligt ned mod modstanden."]$ex$, $ex$[{"title":"Trækker skuldrene op","body":"Traps overtager løftet. Cue: hold skuldrene nede og løft fra siden af skulderen, ikke fra nakken."},{"title":"Svinger vægten op","body":"Bruger momentum i stedet for kontrol. Løft roligt og modstå elastikken på vej ned."}]$ex$,
   'Isolerer sideskulderen for bredde og runde skuldre. Elastikkens stigende modstand passer perfekt til løftets stærkeste punkt øverst.', 'Stå midt på elastikken, fødderne skulderbredde. Grib enderne med arme ned langs siden, let bøj i albuen.', 'Tykkere elastik, eller hold et øjebliks pause i toppen.', 'Tyndere elastik, eller løft én arm ad gangen.',
   1080, false),
  ('band-pullover', 'Band Pullover', 'upper-body-pull', 'isolation', 'band', 'beginner',
   'Lats', '{lats}', '{chest,triceps}', '{abs,rear_delts}',
   'Træk strakte arme ned over kroppen med ryggen, hold core spændt.', $ex$["Fastgør elastikken højt og hold armene næsten strakte.","Træk armene ned i en bue over kroppen mod hoften.","Før bevægelsen fra lats, ikke fra albuerne.","Hold ribbenene nede og core spændt hele vejen."]$ex$, $ex$[{"title":"Bøjer albuerne","body":"Bevægelsen bliver til et pulldown og mister lats-strækket. Cue: hold armene lange med kun en lille fast bøj."},{"title":"Ribbenene flarer ud","body":"Lænden overstrækkes og core slipper. Hold ribbenene trukket ned og maven aktiv gennem hele trækket."}]$ex$,
   'Træner lats gennem en lang strækbane med strakte arme — bygger bredde og lærer at adskille lats fra biceps. God core-udfordring oveni.', 'Fastgør elastikken højt. Stå eller knæl vendt mod forankringen, arme strakte op og frem, core spændt.', 'Tykkere elastik, eller udfør liggende for længere bevægelsesbane.', 'Tyndere elastik, eller forkort banen til du har styr på lats-aktiveringen.',
   1090, false),
  ('band-romanian-deadlift', 'Band Romanian Deadlift', 'lower-body', 'hinge', 'band', 'beginner',
   'Hamstrings', '{hamstrings,glutes}', '{lower_back}', '{abs,forearms}',
   'Skub hoften bagud, hold ryggen flad og mærk strækket i baglåret.', $ex$["Stå på elastikken, hofterne skydes bagud — ikke ned.","Hold ryggen flad og brystet åbent hele vejen.","Læn frem til du mærker stræk i baglåret, ikke længere.","Pres hoften frem og knib glutes i toppen.","Knæene let bøjede og låst — bevægelsen er i hoften."]$ex$, $ex$[{"title":"Runder lænden","body":"Mister neutral ryg når du bøjer frem. Cue: stik brystet frem og træk skulderbladene let sammen, stop før ryggen runder."},{"title":"Bøjer i knæene som en squat","body":"Bevægelsen bliver til en squat i stedet for et hinge. Cue: lås knævinklen og skub kun hoften bagud."}]$ex$,
   'Lærer hinge-mønsteret med lav belastning og konstant spænding fra elastikken — perfekt teknik-byggeklods før tunge deadlifts.', 'Stå midt på elastikken med fødderne i hoftebredde. Tag fat om elastikken med strakte arme, neutral ryg, let bøjede knæ.', 'Tykkere elastik, eller single-leg RDL for mere balance og glute-arbejde.', 'Tyndere elastik eller forkort range til kun halvt stræk.',
   1100, false),
  ('band-row', 'Band Row', 'upper-body-pull', 'pull-horizontal', 'band', 'beginner',
   'Back', '{lats,rear_delts}', '{biceps,traps}', '{forearms,lower_back}',
   'Træk albuerne bagud langs siden og knib skulderbladene sammen.', $ex$["Sid eller stå med spændt mave og oprejst torso.","Træk albuerne bagud langs kroppen, ikke ud til siden.","Knib skulderbladene sammen i slutpositionen.","Hold en kort pause når elastikken rører maven.","Slip kontrolleret tilbage — lad ikke elastikken trække dig."]$ex$, $ex$[{"title":"Trækker med biceps","body":"Albuerne flarer ud og armene gør arbejdet. Cue: tænk på at føre albuerne mod baglommen og lad ryggen trække."},{"title":"Læner kroppen bagud","body":"Bruger momentum fra torsoen til at flytte elastikken. Cue: hold torsoen helt stille og bevæg kun armene."}]$ex$,
   'Bygger trækstyrke og sund holdning med lav skadesrisiko — ideel til at lære skulderbladskontrol uden tung last.', 'Sæt elastikken fast om en stolpe i brysthøjde eller om fødderne ved siddende variant. Greb i hoftebredde, arme strakte, ryggen neutral.', 'Tykkere elastik, single-arm row, eller flyt længere væk for mere modstand.', 'Tyndere elastik eller siddende variant med fødderne som anker for mere stabilitet.',
   1110, false),
  ('band-seated-pulldown', 'Band Seated Pulldown', 'upper-body-pull', 'pull-vertical', 'band', 'beginner',
   'Lats', '{lats}', '{biceps,rear_delts}', '{traps,forearms}',
   'Træk albuerne ned mod siderne og før elastikken mod øvre bryst.', $ex$["Sid oprejst med spændt mave og let lænesvaj.","Start bevægelsen ved at trække skulderbladene ned.","Før albuerne ned langs siderne, ikke frem.","Træk elastikken til øvre bryst, brystet op mod elastikken.","Kontroller vejen op — fuld stræk i toppen uden at lade skuldrene ryge op om ørerne."]$ex$, $ex$[{"title":"Trækker bag nakken","body":"Belaster skuldrene i en dårlig position. Cue: træk altid ned foran kroppen mod øvre bryst."},{"title":"Læner langt tilbage","body":"Gør øvelsen til en row med momentum. Cue: hold torsoen næsten lodret og lad lats arbejde lodret nedad."}]$ex$,
   'Træner det lodrette træk og lats uden behov for pull-up styrke — bygger basen til chins og bredere ryg.', 'Forankr elastikken højt over hovedet. Sid på en bænk eller gulvet, greb bredere end skulderbredde, arme strakte op.', 'Tykkere elastik, single-arm pulldown, eller skift til assisteret pull-up.', 'Tyndere elastik eller smallere greb for lettere træk.',
   1120, false),
  ('band-shrug', 'Band Shrug', 'shoulders', 'isolation', 'band', 'beginner',
   'Traps', '{traps}', '{rear_delts}', '{forearms,neck}',
   'Træk skuldrene lige op mod ørerne og hold kort i toppen.', $ex$["Stå på elastikken, arme strakte ned langs siderne.","Træk skuldrene lige op mod ørerne — ikke frem eller bagud.","Hold en kort pause i toppen og knib traps.","Sænk kontrolleret hele vejen ned til fuld stræk.","Hold armene strakte — det er kun skuldrene der bevæger sig."]$ex$, $ex$[{"title":"Ruller skuldrene","body":"Skulderrullen belaster leddet unødigt uden ekstra trap-arbejde. Cue: træk lige op og ned i en lige bane."},{"title":"Bøjer albuerne","body":"Armene overtager arbejdet. Cue: lås albuerne strakte og løft kun via skuldrene."}]$ex$,
   'Isolerer traps og bygger nakke- og skuldermasse — støtter en stærk overdel og bedre holdning.', 'Stå midt på elastikken med fødderne i skulderbredde. Greb om elastikken, arme strakte ned, oprejst torso.', 'Tykkere elastik eller tilføj pause på 2 sekunder i toppen.', 'Tyndere elastik eller kortere range of motion.',
   1130, false),
