  ('machine-pec-fly', 'Machine Pec Fly', 'upper-body-push', 'isolation', 'machine', 'beginner',
   'Chest', '{chest}', '{front_delts}', '{biceps}',
   'Bløde albuer, før håndtagene sammen i en bue og klem brystet.', $ex$["Hold en let, fast bøjning i albuerne hele vejen.","Før håndtagene sammen i en bred bue — tænk omfavnelse.","Klem brystet hårdt i midten i et øjeblik.","Slip kontrolleret til du føler stræk over brystet.","Hold skuldrene nede og bagud væk fra ørerne."]$ex$, $ex$[{"title":"Bøjer og strækker albuerne","body":"Du laver en pres-bevægelse i stedet for en fly, og triceps overtager. Cue: lås albuevinklen og bevæg kun fra skulderleddet."},{"title":"Skuldrene ruller frem","body":"Du mister brystaktivering og belaster forsiden af skulderen. Cue: træk skulderbladene let sammen og hold brystet højt."}]$ex$,
   'Isolerer brystet gennem fuld adduktion uden at triceps eller balance-krav stjæler arbejdet — ren hypertrofi for chest.', 'Justér sæde så håndtagene er i brysthøjde. Ryg mod puden, let bøjede albuer, brystet løftet før start.', 'Hold et længere klem i midten, eller arbejd én arm ad gangen for større range of motion.', 'Reducer vægten og indskrænk range en smule så skulderen ikke overstrækkes bagud.',
   2720, false),
  ('machine-plate-loaded-leg-extension', 'Machine Plate Loaded Leg Extension', 'lower-body', 'isolation', 'machine', 'beginner',
   'Quads', '{quads}', '{}', '{calves_front}',
   'Stræk knæene fuldt ud, klem quads i toppen og sænk kontrolleret.', $ex$["Justér rullen så den sidder lige over ankelleddet.","Stræk knæene helt ud og klem quads et øjeblik i toppen.","Sænk langsomt — modstå vægten på vej ned.","Hold ryg og hofte plantet mod sædet.","Hold tæerne let trukket op mod skinnebenet."]$ex$, $ex$[{"title":"Svinger vægten op","body":"Du bruger momentum og hoften løfter fra sædet. Cue: sæt tempoet ned og lad quads gøre arbejdet uden gynge."},{"title":"Strækker ikke helt ud","body":"Du stopper kort af fuld ekstension og mister toppen af bevægelsen. Cue: lås knæet og klem i et øjeblik hver gentagelse."},{"title":"Sænker for hurtigt","body":"Du dropper vægten og spilder den excentriske fase. Cue: brug 2-3 sekunder på vej ned."}]$ex$,
   'Eneste øvelse der isolerer quads i fuld knæ-ekstension — bygger lårets forside og styrker det punkt squat ikke rammer.', 'Sid med ryggen mod lænet, knæ-akslen ud for maskinens drejepunkt og rullen lige over anklerne. Greb om håndtagene.', 'Tilføj pause i toppen eller arbejd én ben ad gangen for at finde svagheder.', 'Sæt vægten ned og brug begge ben med kontrolleret tempo til teknikken sidder.',
